#[inductive(combiner_send)]
fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool) {
    let j = pre.combiner.get_Responding_idx();

    // Prove not_waiting_inv
    assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() 
        implies !post.slots.index(i) by {
        if i == j {
            // For index j, we explicitly set slots[j] to false in the transition
            assert(post.slots.index(j) == false);
        } else {
            // For other indices, the slots value remains unchanged from pre to post
            assert(pre.slots.index(i) == post.slots.index(i));
            // Since pre satisfies not_waiting_inv, and client i is Idle in pre,
            // we know pre.slots.index(i) is false
            assert(pre.valid_idx(i) && pre.clients.index(i).is_Idle() ==> !pre.slots.index(i));
            if pre.valid_idx(i) && pre.clients.index(i).is_Idle() {
                assert(!pre.slots.index(i));
                assert(!post.slots.index(i));
            }
        }
    }

    // Prove waiting_inv  
    assert forall |i: nat| #[trigger] post.client_waiting(i) implies
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        if i == j {
            // For index j, we deposited a response, so response_stored(j) should hold
            assert(post.response_stored(j));
            assert(post.request_stored(j) || post.response_stored(j) || post.combiner_has(j));
        } else {
            // For other indices, check what happens based on pre state
            assert(pre.client_waiting(i) == post.client_waiting(i));
            if post.client_waiting(i) {
                // Client was waiting in pre state too
                assert(pre.client_waiting(i));
                // By invariant in pre state:
                assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));

                // Check how each component changed from pre to post:
                // requests: unchanged for i != j
                assert(pre.request_stored(i) == post.request_stored(i));
                // responses: added one at j, others unchanged
                assert(i != j ==> pre.response_stored(i) == post.response_stored(i));
                // combiner state: elements unchanged, idx incremented, so combiner_has for i >= idx might change
                // But since i != j and j = pre.idx, the change in idx doesn't directly affect combiner_has(i) immediately

                // If it was stored in request or response in pre, it's still so in post (for i != j)
                // If it was in combiner in pre, we need to check if it's still there in post
                if pre.request_stored(i) {
                    assert(post.request_stored(i));
                }
                if pre.response_stored(i) && i != j {
                    assert(post.response_stored(i));
                }
                if pre.combiner_has(i) {
                    // Need to verify combiner_has status preserved for i != j
                    // Since idx incremented and j = old_idx, for i > j: same condition
                    // For i < j: should also be same since elems unchanged
                    assert(post.combiner_has(i));
                }
                assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
            }
        }
    }
}

